with TemporaryDirectory(prefix='tuhkar-swipe-') as temp:
    root=Path(temp);files=[]
    for name,text in stubs.items():
        p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text);files.append(str(p))
    subprocess.run(['javac','-encoding','UTF-8','-d',str(root/'classes'),*files,str(Path('app/src/com/luma/media/SwipeDeck.java').resolve())],check=True)
    subprocess.run(['java','-cp',str(root/'classes'),'com.luma.media.SwipePlaybackContract'],check=True)
